/**
 * @method
 * @name fn_OpenIndCodeWin
 * @description desc
 * @param
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_OpenIndCodeWin = function() {
    scwin.w = '375';
    scwin.h = '220';
    scwin.l = screen.width / 2 - scwin.w / 2;
    scwin.t = screen.height / 2 - scwin.h / 2;
    if (scwin.indCodeWin != null) {
        if (!indCodeWin.closed) {
            indCodeWin.close();
        }
    }
    scwin.indCodeWin = window.open("/common/popup_indcode.jsp", "pop_ind", "left=" + scwin.l + ",top=" + scwin.t + ",width=" + scwin.w + ",height=" + scwin.h + ",scrollbars=no,resizable=no");
};




