};



//파일명 추출후 업로드 가능 확장자인지 확인.
/**
 * @method
 * @name fn_getFileNmCheck
 * @description desc
 * @param {string} rn desc
 * @param {string} obj desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_getFileNmCheck = function(rn, obj) {
    var objFile = $("input[name='attachFiles[" + rn + "]']");
    var temp = objFile.val();
    var file_name = temp.substring(temp.lastIndexOf('\\') + 1);
    var file = file_name.substring(file_name.lastIndexOf('.') + 1); //확장자
    //var file = file_name.split(".");

    var temp = $("input[name='attachFiles[" + rn + "]']").val(); //원본파일
    //var temp2 = temp.substring(temp.lastIndexOf('\\')+1);//파일명 확장자포함
    //var temp3 = temp2.substring(temp2.lastIndexOf('.')+1);//확장자
    //var temp4 = temp2.substring(0,temp2.lastIndexOf('.'));//파일명만

    var extList = new Array("hwp", "docx", "doc", "xls", "xlsx", "ppt", "pptx", "pdf", "gif", "jpg", "jpeg", "bmp", "tif", "txt", "drt", "dsd", "png", "zip");
    var fileChk = 0;
    for (var i = 0; i < extList.length; i++) {
        if (file.toLowerCase() == extList[i]) fileChk = fileChk + 1;
    }
    if (fileChk == 0) {
        alert("첨부 불가능한 파일입니다.");
        objFile.replaceWith(objFile.clone(true));
        return false;
    }

    //파일용량체크
    var fileSize = 0;
    var maxSize = 20 * 1024 * 1024; //20MB

    //브라우저확인
    var browser = navigator.appName;
    if (browser == "Microsoft Internet Explorer") {
        var oas = new ActiveXObject("Scripting.FileSystemObject");
        fileSize = oas.getFile(temp).size;
    } else {
        fileSize = obj.files[0].size;
    }
    if (fileSize > maxSize) {
        alert("첨부파일 사이즈는 20MB 이내로 등록 가능합니다.");
        objFile.replaceWith(objFile.clone(true));
        return false;
    }

    //파일명 길이체크

    //alert(file[file.length-2].length);

    /*if(temp4.length > 35){
    	alert("파일명이 35자를 초과하는 파일은 첨부 할 수 없습니다.");
    	$("input[name='attach_file_nm["+rn+"]']").val("");
    	objFile.replaceWith(objFile.clone(true));
    	return;
    }*/

    // 중복파일 체크.

    /* var fileCnt = $("input[name=file_coment]").length;
     for( var i = 0; i < fileCnt; i++ ){
         if( file_name == $("input[name='attach_file_nm["+i+"]']").val() ){
             alert("이미 첨부된 파일입니다.");
     		//$("input[name='attachFiles["+rn+"]']").val("");
     		$("input[name='attach_file_nm["+rn+"]']").val("");
     		objFile.replaceWith(objFile.clone(true));
     		return;
         }        
     }*/
};
